import { createFileRoute, Link, Outlet, useRouterState } from "@tanstack/react-router";
import { Gamepad2 } from "lucide-react";
import { useSiteConfig } from "@/lib/site-config";
import { GAME_FLAGS, gameFlagFor, useFeatureGuard } from "@/lib/feature-guard";
import { GameFocusLock } from "@/components/game-focus-lock";

const GAMES_DESCRIPTION =
  "DAP Arcade — a small library of free browser games generated by DAP AI: 2048, Snake, Spacewar, DAP Track, Flappy, Brick Breaker and more.";

export const Route = createFileRoute("/games")({
  head: () => ({
    meta: [
      { title: "DAP Arcade — Free browser games by DAP AI" },
      { name: "description", content: GAMES_DESCRIPTION },
      { property: "og:title", content: "DAP Arcade — Free browser games by DAP AI" },
      { property: "og:description", content: GAMES_DESCRIPTION },
      { property: "og:type", content: "website" },
      { property: "og:url", content: "https://dapai.lovable.app/games" },
      { name: "twitter:card", content: "summary_large_image" },
      { name: "twitter:title", content: "DAP Arcade — Free browser games by DAP AI" },
      { name: "twitter:description", content: GAMES_DESCRIPTION },
    ],
    scripts: [
      {
        type: "application/ld+json",
        children: JSON.stringify({
          "@context": "https://schema.org",
          "@type": "CollectionPage",
          name: "DAP Arcade",
          description: GAMES_DESCRIPTION,
          url: "https://dapai.lovable.app/games",
          isPartOf: { "@type": "WebSite", name: "DAP AI", url: "https://dapai.lovable.app" },
          mainEntity: {
            "@type": "ItemList",
            itemListElement: [
              ["2048", "/games/2048"],
              ["Snake", "/games/snake"],
              ["Spacewar", "/games/spacewar"],
              ["DAP Track", "/games/daptrack"],
              ["River Crosser", "/games/river"],
              ["Flappy", "/games/flappy"],
              ["Brick Breaker", "/games/breakout"],
              ["Stunt Racer", "/games/stunt"],
            ].map(([name, path], i) => ({
              "@type": "ListItem",
              position: i + 1,
              name,
              url: `https://dapai.lovable.app${path}`,
            })),
          },
        }),
      },
    ],
  }),
  component: GamesLayout,
});

const GAMES = [
  { to: "/games/2048" as const, label: "2048", emoji: "🟨" },
  { to: "/games/snake" as const, label: "Snake", emoji: "🐍" },
  { to: "/games/spacewar" as const, label: "Spacewar", emoji: "🚀" },
  { to: "/games/daptrack" as const, label: "DAP Track", emoji: "🏎️" },
  { to: "/games/river" as const, label: "River Crosser", emoji: "🐸" },
  { to: "/games/flappy" as const, label: "Flappy", emoji: "🐤" },
  { to: "/games/breakout" as const, label: "Brick Breaker", emoji: "🧱" },
  { to: "/games/stunt" as const, label: "Stunt Racer", emoji: "🛞" },
] as const;

function GamesLayout() {
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const siteConfig = useSiteConfig();

  // The arcade switch and the per-game switches both send you home the
  // moment the admin flips them, even in the middle of a run.
  const gameFlag = gameFlagFor(pathname);
  const arcadeOff = useFeatureGuard(siteConfig.flags.games ? null : "games");
  const gameOff = useFeatureGuard(siteConfig.flags.games ? gameFlag : null);
  if (arcadeOff || gameOff) return null;

  const visible = GAMES.filter(
    (g) => siteConfig.flags[GAME_FLAGS[g.to]] !== false
  );

  return (
    <div className="flex min-h-[calc(100vh-3.5rem)] flex-col md:flex-row">
      <aside className="w-full shrink-0 border-b border-border bg-card/40 p-3 md:w-56 md:border-b-0 md:border-r">
        <Link
          to="/games"
          className="mb-3 flex items-center gap-2 text-sm font-semibold text-foreground hover:text-primary"
        >
          <Gamepad2 className="h-4 w-4 text-primary" /> Arcade
        </Link>
        <nav className="flex gap-2 overflow-x-auto md:flex-col md:overflow-visible">
          {visible.map((g) => {
            const active = pathname === g.to;
            return (
              <Link
                key={g.to}
                to={g.to}
                className={`flex items-center gap-2 rounded-lg px-3 py-2 text-sm transition-all hover:translate-x-0.5 hover:bg-sidebar-accent ${
                  active ? "bg-sidebar-accent font-medium text-foreground" : "text-muted-foreground"
                }`}
              >
                <span className="text-base">{g.emoji}</span>
                <span>{g.label}</span>
              </Link>
            );
          })}
        </nav>
      </aside>
      <div className="flex-1 p-4 md:p-8">
        <GameFocusLock>
          <Outlet />
        </GameFocusLock>
      </div>
    </div>
  );
}
